import{_ as i,o as a,c as l,ag as t}from"./chunks/framework.BwSLX4ak.js";const k=JSON.parse('{"title":"升级与自动更新","description":"","frontmatter":{},"headers":[],"relativePath":"shitbot/updating.md","filePath":"shitbot/updating.md"}'),s={name:"shitbot/updating.md"};function o(d,e,p,h,n,c){return a(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="升级与自动更新" tabindex="-1">升级与自动更新 <a class="header-anchor" href="#升级与自动更新" aria-label="Permalink to &quot;升级与自动更新&quot;">​</a></h1><h2 id="升级前" tabindex="-1">升级前 <a class="header-anchor" href="#升级前" aria-label="Permalink to &quot;升级前&quot;">​</a></h2><ol><li>阅读目标版本的 <a href="https://github.com/hutuyee/ShitBot/releases" target="_blank" rel="noreferrer">Release Notes</a>；</li><li>备份数据库；</li><li>备份 <code>config.yml</code>、<code>commands.yml</code>、<code>lang/</code>、<code>templates/</code>、<code>image-templates/</code> 和自定义图片资源；</li><li>群组服确认代理与后端是否需要同时升级；</li><li>不要在服务端运行期间直接复制 SQLite 数据库。</li></ol><p>代理—后端协议发生变化时，必须同时升级代理和全部 Spigot 后端。混用不同协议版本可能导致命令、TPS 查询或联动更新失败。</p><p>启用高级图片模板的实例还要求官方 Release 存在同版本 <code>ShitBotRenderer</code>。平台插件更新后，下一次启动会按新版本检查组件缓存；只有高级模板总开关开启时才会下载新组件。</p><h2 id="手动升级" tabindex="-1">手动升级 <a class="header-anchor" href="#手动升级" aria-label="Permalink to &quot;手动升级&quot;">​</a></h2><ol><li>停止服务器或代理；</li><li>下载当前平台的新 JAR；</li><li>移走旧 JAR，只保留一个 ShitBot 平台 JAR；</li><li>放入新 JAR；</li><li>启动并观察配置迁移与数据库迁移日志；</li><li>对照新版本默认配置补充新增配置项；</li><li>执行 <code>/shitbot status</code>；</li><li>验证 OneBot、绑定、转发和快捷命令。</li></ol><p>不要通过插件管理器热卸载旧 JAR 再加载新 JAR。</p><p>从 <code>config-version: 1</code> 升级时，首次加载会把旧 <code>config.yml</code> 的回复、通知、内置别名/用法和图片标题自动导入 <code>lang/zh_CN.yml</code>，但不会改写旧配置。确认导入结果后，再自行清理旧配置中的废弃文本项。迁移完成状态记录在 <code>zh_CN.yml</code> 的 <code>_migration.legacy-config-v1</code>，因此后续 reload 不会重复覆盖。</p><h2 id="shitbot-update" tabindex="-1"><code>/shitbot update</code> <a class="header-anchor" href="#shitbot-update" aria-label="Permalink to &quot;`/shitbot update`&quot;">​</a></h2><p>有 <code>shitbot.admin</code> 权限的管理员可以执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/shitbot update</span></span></code></pre></div><p>更新器会：</p><ol><li>查询最新 GitHub Release；</li><li>选择当前平台的 JAR；</li><li>下载 JAR、<code>.sha256</code> 和 <code>.sig</code>；</li><li>校验下载地址、文件大小和 SHA-256；</li><li>使用内置公钥验证独立 RSA 签名；</li><li>检查 JAR 平台描述、主类和内嵌版本；</li><li>将当前 JAR 备份为同目录的 <code>.bak</code>；</li><li>替换 JAR，并提示手动重启。</li></ol><p>更新命令不会热重载插件。完成后必须正常重启服务器或代理。</p><p>任意校验失败时，更新器会保留当前 JAR。不要通过手动删除 <code>.sha256</code>、<code>.sig</code> 或修改 Release 文件来绕过验证。</p><h2 id="群组服联动更新" tabindex="-1">群组服联动更新 <a class="header-anchor" href="#群组服联动更新" aria-label="Permalink to &quot;群组服联动更新&quot;">​</a></h2><p>在 BungeeCord 执行 <code>/shitbot update</code> 时，代理会将同一 Release 中的 Spigot JAR和校验元数据发送到 <code>backend-transport.endpoints</code> 中已配置的后端。</p><ul><li>每个后端独立验证并替换自己的 JAR；</li><li>代理会分别返回各后端结果；</li><li>未配置 endpoint 的子服不会被扫描或更新；</li><li>更新完成后仍需手动重启代理和各后端；</li><li>后端模式的 Spigot 不会独立检查 GitHub，由代理负责通知和分发。</li></ul><p>执行联动更新前，确认代理—后端通道正常，并为各端数据库与配置创建备份。</p><h2 id="自动检查" tabindex="-1">自动检查 <a class="header-anchor" href="#自动检查" aria-label="Permalink to &quot;自动检查&quot;">​</a></h2><p>插件启动后会在后台检查 GitHub Release。检查不会占用服务端主线程；最新结果发生变化时会写入插件数据目录下的 <code>update-cache.json</code>。</p><p>有 <code>shitbot.admin</code> 权限的管理员上线时，会收到可用新版本和 Release 链接提示。自动检查只负责通知，不会未经命令自动替换插件。</p><h2 id="更新失败排查" tabindex="-1">更新失败排查 <a class="header-anchor" href="#更新失败排查" aria-label="Permalink to &quot;更新失败排查&quot;">​</a></h2><p>检查：</p><ul><li>当前实例能够访问 <code>api.github.com</code> 和 GitHub Release 下载域名；</li><li>Release 包含当前平台 JAR；</li><li>高级模板已启用时，Release 同时包含同版本 <code>ShitBotRenderer</code>；</li><li>同时存在对应的 <code>.jar.sha256</code> 和 <code>.jar.sig</code>；</li><li>JAR、校验文件和签名来自同一个 Release；</li><li>插件目录可写；</li><li>当前 JAR 路径可识别且没有被其他程序锁定；</li><li>群组服的代理—后端通道处于正常状态。</li></ul><p>如果自动更新失败，可以保留日志后改用手动升级，但仍应从官方 Release 下载。</p><h2 id="发布维护者-签名密钥" tabindex="-1">发布维护者：签名密钥 <a class="header-anchor" href="#发布维护者-签名密钥" aria-label="Permalink to &quot;发布维护者：签名密钥&quot;">​</a></h2><p>普通服主不需要配置任何更新公钥或私钥。公钥内置在 ShitBotCore 中，私钥只应保存在 GitHub Actions 的 <code>SHITBOT_UPDATE_PRIVATE_KEY</code> Secret。</p><p>首次生成或轮换密钥：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> genpkey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -algorithm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RSA</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pkeyopt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsa_keygen_bits:3072</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-private-key.pem</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pkey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-private-key.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -pubout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update-public-key.pem</span></span></code></pre></div><p>轮换时需要：</p><ol><li>更新 ShitBotCore 内置公钥；</li><li>更新仓库 Secret 中的私钥；</li><li>通过可信的手动升级方式把包含新公钥的版本部署到现有实例；</li><li>再使用新私钥签署后续 Release。</li></ol><p>私钥不能提交到仓库、打包进 JAR 或分发给服主。</p>',34)])])}const u=i(s,[["render",o]]);export{k as __pageData,u as default};
